    /**
     * Recorded By Id
     */
    recorded_by_id?: string | null;
    /**
     * Recorded By Name
     */
    recorded_by_name?: string | null;
    /**
     * Stripe Dashboard Url
     */
    stripe_dashboard_url?: string | null;
    /**
     * Id
     */
    id?: string | null;
    /**
     * Amount
     */
    amount: string;
    /**
     * Currency
     */
    currency: string;
    /**
     * Notes
     */
    notes?: string | null;
    /**
     * Created At
     */
    created_at: string;
